"""
title: Jira Search
description: A robust Jira integration tool to search issues via the new JQL API endpoint.
repository: https://github.com/olive-soft/open-webui-tools
author: @ameurghorbel
author_url: https://github.com/olive-soft
version: 1.0.0
changelog:
  - 0.0.1: Initial implementation
  - 0.1.0: Added support for Personal Access Token authentication and user settings
  - 1.0.0: Updated to use /rest/api/3/search/jql (deprecated /search replaced), improved error handling and logging
"""

import base64
import json
from typing import Any, Awaitable, Callable, Dict, List
import requests
from pydantic import BaseModel, Field


# ------------------- EVENT EMITTER -------------------
class EventEmitter:
    def __init__(self, event_emitter: Callable[[dict], Awaitable[None]]):
        self.event_emitter = event_emitter

    async def emit_status(self, description: str, done: bool, error: bool = False):
        icon = "❌" if error else ("✅" if done else "🔎")
        status = "complete" if done else "in_progress"
        await self.event_emitter(
            {
                "type": "status",
                "data": {
                    "description": f"{icon} {description}",
                    "status": status,
                    "done": done,
                },
            }
        )

    async def emit_message(self, content: str):
        await self.event_emitter({"type": "message", "data": {"content": content}})

    async def emit_source(self, name: str, url: str, content: str, html: bool = False):
        await self.event_emitter(
            {
                "type": "citation",
                "data": {
                    "document": [content],
                    "metadata": [{"source": url, "html": html}],
                    "source": {"name": name},
                },
            }
        )


# ------------------- JIRA CLIENT -------------------
class Jira:
    def __init__(
        self, username: str, api_key: str, base_url: str, api_key_auth: bool = True
    ):
        self.base_url = base_url.rstrip("/")
        self.headers = self.authenticate(username, api_key, api_key_auth)

    def authenticate_api_key(self, username: str, api_key: str) -> Dict[str, str]:
        auth_string = f"{username}:{api_key}"
        encoded_auth = base64.b64encode(auth_string.encode("utf-8")).decode("utf-8")
        return {
            "Authorization": "Basic " + encoded_auth,
            "Accept": "application/json",
            "Content-Type": "application/json",
        }

    def authenticate_personal_access_token(self, access_token: str) -> Dict[str, str]:
        return {
            "Authorization": f"Bearer {access_token}",
            "Accept": "application/json",
            "Content-Type": "application/json",
        }

    def authenticate(
        self, username: str, api_key: str, api_key_auth: bool
    ) -> Dict[str, str]:
        if api_key_auth:
            return self.authenticate_api_key(username, api_key)
        else:
            return self.authenticate_personal_access_token(api_key)

    # -------- NEW JIRA SEARCH ENDPOINT --------
    def search(self, query: str, limit: int = 10) -> List[Dict[str, Any]]:
        """
        Executes a Jira JQL search using the new /rest/api/3/search/jql endpoint.
        Returns a list of issue IDs and keys.
        """
        url = f"{self.base_url}/rest/api/3/search/jql"
        body = {"jql": query, "maxResults": limit}

        try:
            response = requests.post(url, headers=self.headers, json=body, timeout=30)
            print("📡 Jira POST URL:", url)
            print("📋 Status:", response.status_code)
            print("📦 Response snippet:", response.text[:400])

            response.raise_for_status()
            data = response.json()

            # Validate response
            if "issues" not in data:
                raise Exception(
                    "; ".join(data.get("errorMessages", ["Unexpected response"]))
                )

            return [
                {"id": issue.get("id"), "key": issue.get("key")}
                for issue in data["issues"]
            ]

        except requests.exceptions.RequestException as e:
            raise Exception(f"HTTP request to Jira failed: {e}")
        except Exception as e:
            raise Exception(f"Jira search error: {e}")


# ------------------- TOOL DEFINITION -------------------
class Tools:
    def __init__(self):
        self.valves = self.Valves()

    # ---------- DEFAULT SETTINGS ----------
    class Valves(BaseModel):
        base_url: str = Field(
            "https://example.atlassian.net",
            description="The base URL of your Jira Cloud instance.",
        )
        username: str = Field(
            "user@example.com",
            description="Default Jira username (usually your Atlassian email).",
        )
        api_key: str = Field(
            "YOUR_API_TOKEN",
            description="Default API key or Personal Access Token.",
        )
        result_limit: int = Field(
            10,
            description="Maximum number of issues to retrieve.",
        )

    # ---------- USER OVERRIDES ----------
    class UserValves(BaseModel):
        api_key_auth: bool = Field(
            True,
            description="Use Basic Auth (email + API key). Disable for PAT-based auth.",
        )
        username: str = Field(
            "",
            description="Atlassian username (email). Leave empty to use default.",
        )
        api_key: str = Field(
            "",
            description="API key or PAT. Leave empty to use default.",
        )

    # ---------- MAIN SEARCH FUNCTION ----------
    async def search_jira(
        self,
        query: str,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        __user__: dict = {},
    ) -> str:
        """
        Perform a Jira JQL search via the new API and emit real-time progress messages.
        :param query: JQL query string.
        :return: JSON string containing issue IDs and keys.
        """
        event_emitter = EventEmitter(__event_emitter__)
        await event_emitter.emit_status(f"Searching Jira for '{query}'...", False)

        try:
            # Extract user or default credentials
            if __user__ and "valves" in __user__:
                user_valves = __user__["valves"]
                api_key_auth = user_valves.api_key_auth
                api_username = user_valves.username or self.valves.username
                api_key = user_valves.api_key or self.valves.api_key
            else:
                api_username = self.valves.username
                api_key = self.valves.api_key
                api_key_auth = True

            jira = Jira(api_username, api_key, self.valves.base_url, api_key_auth)
            results = jira.search(query, self.valves.result_limit)

            await event_emitter.emit_status(
                f"✅ Search complete: {len(results)} issues found.", True
            )
            return json.dumps(results, indent=2)

        except Exception as e:
            await event_emitter.emit_status(f"❌ Jira search failed: {e}", True, True)
            return f"Error: {e}"
